import random

def solve_optimal(nums, target):
    reachable = 1
    for x in nums:
        reachable |= reachable << x
    return bool((reachable >> target) & 1)

def solve_brute(nums, target):
    n = len(nums)
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask >> i & 1:
                total += nums[i]
        if total == target:
            return True
    return False

def gen(rng, size):
    n = rng.randint(0, {"tiny": 3, "small": 7, "large": 11}[size])
    nums = [rng.randint(0, 15) for _ in range(n)]
    return [nums, rng.randint(0, 40)]

def validate(args):
    nums, target = args
    return 0 <= len(nums) <= 20 and all(x >= 0 for x in nums) and target >= 0
